import React, { useContext, useState, useEffect } from 'react';
import { AppContext } from './AppContext';
import './SettingsPanel.css';

function SettingsPanel() {
  const { theme, setTheme, language, setLanguage, token } = useContext(AppContext);

  // Local form state for user info
  const [age, setAge] = useState('');
  const [gender, setGender] = useState('');
  const [message, setMessage] = useState(null);

  // On mount, you might want to load current user info from backend or context
  useEffect(() => {
    // Ideally fetch user info from backend here and setAge, setGender
    // For demo, let's assume defaults or stored somewhere:
    // You can also pass user info in context if you want.
  }, []);

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const handleSave = async () => {
    setMessage(null);
    try {
      const res = await fetch('/user/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`, // if needed
        },
        body: JSON.stringify({ age, gender }),
      });
      if (!res.ok) throw new Error('Update failed');
      setMessage('User info updated successfully!');
    } catch (error) {
      setMessage('Failed to update user info.');
      console.error(error);
    }
  };

  return (
    <div className={`settings-panel ${theme === 'dark' ? 'dark' : ''}`}>
      <h2>Settings</h2>

      <div className="setting-group">
        <label>Theme</label>
        <button className="theme-toggle-btn" onClick={toggleTheme}>
          Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
        </button>
      </div>

      <div className="setting-group">
        <label>Language</label>
        <select value={language} onChange={handleLanguageChange}>
          <option value="en">English</option>
          <option value="fr">French</option>
          <option value="ar">Arabic</option>
        </select>
      </div>

      <div className="setting-group">
        <label>Age</label>
        <input
          type="number"
          min="1"
          max="120"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          placeholder="Enter your age"
        />
      </div>

      <div className="setting-group">
        <label>Gender</label>
        <select value={gender} onChange={(e) => setGender(e.target.value)}>
          <option value="">Select gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>
      </div>

      <button className="save-btn" onClick={handleSave}>
        Save
      </button>

      {message && <div className="message">{message}</div>}
    </div>
  );
}

export default SettingsPanel;
